import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int c = sc.nextInt();
        int[] arr = {a, b, c};
        Arrays.sort(arr);
        int x = arr[0];
        int y = arr[1];
        int z = arr[2];
        int res = 0;
        while (x + y <= z) {
            x++;
            res++;
            Arrays.sort(new int[]{x, y, z});
            // re-sort
            int[] temp = {x, y, z};
            Arrays.sort(temp);
            x = temp[0];
            y = temp[1];
            z = temp[2];
        }
        System.out.println(res);
    }
}
